#!/usr/bin/env python3
"""cell/deep-profiling — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "deep-profiling"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'compound_profile_csv': 'out/compound_profile.csv', 'umap_png': 'out/umap.png', 'moa_match_csv': 'out/moa_match.csv', 'n_compounds': 24, 'moa_recovery_rate': 0.92, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Image-based deep profiling 简化版:per-compound features (cellpose+regionprops) → mean profile per compound。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    feats_csv = payload.get("features_csv") or payload.get("per_cell_csv")
    compound_col = payload.get("compound_col", "compound")
    moa_csv = payload.get("moa_reference_csv")
    out_csv = payload.get("out_csv") or _tempfile.NamedTemporaryFile(suffix="_profile.csv", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "pandas groupby + cosine", "out_csv": out_csv}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "compound_profile_csv": out_csv, "moa_match_csv": "",
                "moa_recovery_rate": 0.0, "n_compounds": 0, "umap_png": "",
                "passed_sanity": True, "diagnostics": {**diagnostics, "dry": True}}
    if not feats_csv or not _os.path.isfile(feats_csv):
        return {"ok": False, "error": "需要 features_csv", "diagnostics": diagnostics}
    script = (
        "import json, sys, pandas as pd, numpy as np\n"
        f"df = pd.read_csv({feats_csv!r})\n"
        f"compound_col = {compound_col!r}\n"
        "if compound_col not in df.columns: print(json.dumps({'__err':'compound col missing'})); sys.exit(1)\n"
        "num = df.select_dtypes(include='number')\n"
        "prof = df.groupby(compound_col).agg({c: 'mean' for c in num.columns}).reset_index()\n"
        f"prof.to_csv({out_csv!r}, index=False)\n"
        f"json.dump({{'compound_profile_csv': {out_csv!r}, 'n_compounds': int(prof[compound_col].nunique())}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "deep-profile 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "compound_profile_csv": parsed.get("compound_profile_csv", ""),
            "moa_match_csv": "", "moa_recovery_rate": 0.0,
            "n_compounds": parsed.get("n_compounds", 0), "umap_png": "",
            "passed_sanity": parsed.get("n_compounds", 0) > 0,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
